function createRateLimiter({ capacity, refillRate }) {
  const buckets = new Map();
  const refillRatePerMs = refillRate / 1000; // tokens per millisecond

  return {
    allow(key) {
      const now = Date.now();
      let bucket = buckets.get(key);
      if (!bucket) {
        bucket = { tokens: capacity, lastRefill: now };
        buckets.set(key, bucket);
      }

      // Refill tokens based on elapsed time
      const elapsed = now - bucket.lastRefill;
      const addedTokens = elapsed * refillRatePerMs;
      bucket.tokens = Math.min(capacity, bucket.tokens + addedTokens);
      bucket.lastRefill = now;

      if (bucket.tokens >= 1) {
        bucket.tokens -= 1;
        return Promise.resolve();
      } else {
        return Promise.reject(new Error('Rate limit exceeded'));
      }
